#include <iostream>
#include <string>

int main() {
    std::string inp_str;
    std::getline(std::cin, inp_str);
    while (inp_str.length() > 2 && inp_str.substr(1, 3) == "dot") {
        size_t dot_index = inp_str.find("dot", 1);
        if (dot_index == std::string::npos) break;
        inp_str.replace(dot_index, 3, ".");
    }
    size_t at_index = inp_str.find("at", 1);
    if (at_index != std::string::npos) {
        inp_str.replace(at_index, 2, "@");
    }
    std::cout << inp_str << std::endl;
    return 0;
}
